function activate(view){if(view!=='cameras'&&typeof cameraActiveRequest!=='undefined'&&cameraActiveRequest)cameraActiveRequest.cancelled=true;document.querySelectorAll('.view').forEach(node=>node.classList.toggle('active',node.id==='view-'+view));document.querySelectorAll('[data-view]').forEach(node=>node.classList.toggle('active',node.dataset.view===view));$('mainNavigation').classList.remove('mobile-open');$('mobileNavToggle').setAttribute('aria-expanded','false');if(objectForView[view]&&view!=='projects'){const container=document.querySelector('[data-object-list="'+objectForView[view]+'"]');if(container&&!container.dataset.loaded){container.dataset.loaded='true';renderObject(objectForView[view],container)}}renderDashboard(view,document.querySelector('[data-dashboard="'+view+'"]'));if(view==='projects')renderWorkPlan();if(view==='records')loadBrowser();if(view==='sync')loadCommands();if(view==='cameras')loadCameras();if(view==='etna')loadEtna();}
