async function initVintageSelector(){const select=document.createElement('select');select.id='vintageYear';select.setAttribute('aria-label','Vintage year');select.title='Vintage year';document.querySelector('.top-actions').prepend(select);let source=[];for(const object of ['seasons','vintage_summaries','harvest_lots']){try{source.push(...await rawRecords(object))}catch(_error){}}const years=[...new Set(source.map(recordYear).filter(Boolean))].sort((a,b)=>b-a);if(!years.includes(selectedYear))years.unshift(selectedYear);select.replaceChildren(...years.map(year=>new Option(String(year),String(year))));select.value=String(selectedYear);select.onchange=()=>{selectedYear=Number(select.value);const url=new URL(location.href);url.searchParams.set('year',String(selectedYear));history.pushState({year:selectedYear},'',url);resetYearViews()};window.addEventListener('popstate',()=>{const year=Number(new URL(location.href).searchParams.get('year'));if(year&&year!==selectedYear){selectedYear=year;select.value=String(year);resetYearViews()}});}
