function installApprovedAdminViews(){addAdminView('cameras','Cameras','◉','<div class="section-title"><div><p class="eyebrow dark">ADMIN · STILL IMAGES</p><h2>Estate cameras</h2></div><button type="button" id="refreshCameraCatalog">Refresh list</button></div><p class="privacy-boundary">Approved administrator only. Each request creates one short-lived still directly from Home Assistant; no image is stored on this website.</p><div id="cameraGrid" class="camera-grid"><p class="empty">Open Cameras to load the approved cameras.</p></div>');addAdminView('docs','Docs','?','<div class="section-title"><div><p class="eyebrow dark">ADMIN · HELP</p><h2>Remote ERP guide</h2></div></div><div class="remote-integrity docs-grid"><p><b>Authority</b><span>Home Assistant remains authoritative. This site contains only approved reporting objects.</span></p><p><b>Offline edits</b><span>Edits are queued with a unique ID and expected revision until HA validates them.</span></p><p><b>Conflicts</b><span>A changed source revision stops the edit for review. Nothing is silently overwritten.</span></p><p><b>Freshness</b><span>Last sync and data age are always visible. Stale data is identified explicitly.</span></p><p><b>Vintage year</b><span>The selected year filters dated reporting records; current equipment and live status remain global.</span></p><p><b>Privacy</b><span>Financial, security and authentication data are not part of this replica.</span></p></div>');}
