function detailLabel(key,value,data){if(key==='current_container_id')return lookup('cellar_containers',value,['name','code'])||'Vessel not linked';if(key==='block_id')return lookup('vineyard_blocks',value,['code','name'])||'Block not linked';if(key==='variety_id')return lookup('grape_varieties',value,['name','canonical_name'])||'Variety not mapped';if(key==='sample_id'){const sample=lookups.lab_samples?.get(value);return sample?.sample_code||sample?.name||'Laboratory sample';}return displayValue(value);}
