function normalizeOptions(options){options.challenge=b64url.decode(options.challenge);if(options.user)options.user.id=b64url.decode(options.user.id);if(options.excludeCredentials)options.excludeCredentials=options.excludeCredentials.map(item=>({...item,id:b64url.decode(item.id)}));return options;}
function registration(credential){return{id:b64url.encode(credential.rawId),clientDataJSON:b64url.encode(credential.response.clientDataJSON),attestationObject:b64url.encode(credential.response.attestationObject),transports:credential.response.getTransports?credential.response.getTransports():[]};}
